export function translateControlsDOM(container, lang) {
    if (!container) return;
    const dict = i18n.controls[lang];
    if (!dict) return;

    // Translate labels and text nodes
    const walk = (node) => {
        if (node.nodeType === Node.TEXT_NODE) {
            const trimmed = node.nodeValue.trim();
            if (trimmed && dict[trimmed]) {
                node.nodeValue = node.nodeValue.replace(trimmed, dict[trimmed]);
            }
        } else if (node.nodeType === Node.ELEMENT_NODE) {
            // check button text
            if (node.tagName === 'BUTTON' || node.classList.contains('toggle-label')) {
                const trimmed = node.textContent.trim();
                if (dict[trimmed]) {
                    node.textContent = dict[trimmed];
                    return;
                }
            }
            for (let child of node.childNodes) {
                walk(child);
            }
        }
    };

    walk(container);
}
